WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_nov_sort'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '微材料统筹排序', 'kp-ms-nov-sort', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "新颖题型：微材料统筹排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "轻重缓急，四象限法则。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“你今天上午要处理 5 件事：1. 领导要材料；2. 群众上访；3. 下属请假；4. 亲戚来访；5. 开会。你该如何排序？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、高分破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝对不能按照 12345 顺着排！必须向考官解释你排序的【原则】。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一原则（重要且紧急）：群众上访情绪激动，涉及社会稳定，必须第一时间安抚处理（排第一）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二原则（重要但不紧急/可授权）：领导要材料，如果在限定时间内，可以先处理更紧急的，或者把寻找基础数据的工作授权给下属去办。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第三原则（私事靠后）：亲戚来访属于私事，无论如何只能放在下班后或午休时间处理，绝不能挤占工作时间。"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "答题结构：我排序的原则是“公事优先于私事，紧急优先于日常”。因此我的顺序是 2 -> 1 -> 3 -> 5 -> 4。具体处理方式如下..."}]}]}$$ AS jsonb), NULL, '微材料统筹排序的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "新颖题型", "统筹排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_nov_sort", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
